"""Book-only Grade 9 General selection. PyMuPDF and SymPy required.
Usage: python scripts/build-grade9-general-textbook-bank.py /path/9-1.pdf /path/9-2.pdf
Original book data are retained; only MCQ choices, prompts adapting to MCQ, and worked keys are added.
"""
from pathlib import Path
import hashlib,json,sys
import fitz
import sympy as S
ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'public/data/exam-banks/9g3-term1';(OUT/'assets').mkdir(parents=True,exist_ok=True)
books={i:fitz.open(sys.argv[i]) for i in [1,2]}
assert [len(books[i]) for i in [1,2]]==[134,147]
parts={str(i):dict(file_name=Path(sys.argv[i]).name,sha256=hashlib.sha256(Path(sys.argv[i]).read_bytes()).hexdigest(),printed_start=1 if i==1 else 135,pdf_pages=len(books[i])) for i in [1,2]}
questions=[];assets={}
def source(page,ex,mcq=True):
 part=1 if page<=134 else 2
 return dict(book_part=part,book_sha256=parts[str(part)]['sha256'],printed_page=page,pdf_page=page-parts[str(part)]['printed_start']+1,exercise=str(ex),adaptation='mcq' if mcq else 'transcription')
def crop(id,page,box,ex):
 src=source(page,ex,False);p=books[src['book_part']][src['pdf_page']-1];rect=fitz.Rect(box[0]*p.rect.width,box[1]*p.rect.height,box[2]*p.rect.width,box[3]*p.rect.height)
 pix=p.get_pixmap(matrix=fitz.Matrix(3,3),clip=rect);pix.save(OUT/f'assets/{id}.png')
 assets[id]=dict(src=f'assets/{id}.png',width=pix.width,height=pix.height,alt_text=f'Original textbook visual, Reveal p. {page}, {ex}.',source=src,crop_box=list(box));return id
def text(v):return 'TEXT:'+v
def mc(lo,page,ex,instruction,expr,correct,wrong,why,image=None):
 i=sum(q['learning_outcome_id']==f'LO{lo:02}' for q in questions)+1
 vals=[correct,*wrong];texts=[S.latex(v) if isinstance(v,S.Basic) else str(v) for v in vals]
 assert len(vals)==len(set(texts))==4,(lo,ex,texts)
 if all(isinstance(v,S.Basic) for v in vals):assert all(S.simplify(vals[a]-vals[b])!=0 for a in range(4) for b in range(a))
 order=list(range(4));shift=(lo+i)%4;order=order[shift:]+order[:shift]
 opts=[dict(id='ABCD'[n],text=texts[k][5:] if texts[k].startswith('TEXT:') else texts[k],**({} if texts[k].startswith('TEXT:') else dict(math_latex=texts[k]))) for n,k in enumerate(order)]
 ans=opts[order.index(0)]
 questions.append(dict(id=f'G9G-BOOK-Q{lo:02}-MCQ-{i:02}',learning_outcome_id=f'LO{lo:02}',type='mcq',display_number=f'{lo}.{i}',instruction=instruction,stem=instruction+' '+expr,math_latex=expr,options=opts,marks=None,answer=dict(correct_option_id=ans['id'],correct_option_text=ans['text'],explanation=why),diagram_asset_ids=[image] if image else [],source=source(page,ex)))
def num(lo,page,ex,prompt,expr,ans,why,image=None):
 ans=S.Rational(str(ans));mc(lo,page,ex,prompt,expr,ans,[ans+1,ans-1,-ans if ans!=0 and ans not in [S.Rational(-1,2),S.Rational(1,2)] else ans+3],why,image)
def pt(prompt,answer,marks=10,latex='',height=30):return dict(id='a',prompt=prompt,marks=marks,math_latex='',workspace=dict(height_mm=height),answer=dict(model_answer_and_marking=answer,math_latex=latex))
def fr(lo,page,ex,instruction,expr,ps,graph=False):
 i=sum(q['learning_outcome_id']==f'LO{lo:02}' for q in questions)+1
 assert sum(p['marks'] for p in ps)==10
 for k,p in enumerate(ps):p['id']=chr(97+k)
 questions.append(dict(id=f'G9G-BOOK-Q{lo:02}-FRQ-{i:02}',learning_outcome_id=f'LO{lo:02}',type='frq',display_number=f'{lo}.{i}',instruction=instruction,stem=instruction+' '+expr,math_latex=expr,parts=ps,marks=10,diagram_asset_ids=[],coordinate_workspace=graph,source=source(page,ex,False)))
