for ex,eq,ans in [(9,'-10x+2y=12',5*x+6),(10,'4y+12x=16',-3*x+4),(11,'-5x+15y=-30',x/3-2),(12,'6x-3y=-18',2*x+6)]:mc(12,235,ex,'Write in slope-intercept form. Options give y.',eq,ans,[-ans,ans+1,ans-x],'Isolate y by moving the x-term and dividing every term by the coefficient of y.')
