# Coverage mapping: extra subparts are clearly cited, never invented numerical variants.
topics=[('Numerical expressions','التعابير العددية','Group words such as sum and difference with parentheses.',9,'11–14'),('Distributive Property','خاصية التوزيع','a(b+c)=ab+ac; distribute negative factors carefully.',42,'23–26'),('Addition and subtraction equations','معادلات الجمع والطرح','Apply the same addition or subtraction to both sides.',81,'1–4'),('Rearrange formulas','إعادة ترتيب الصيغ','Isolate the requested variable; state nonzero divisor assumptions.',125,'11–14'),('Properties of equality','خصائص المساواة','Reflexive A=A; symmetric A=B⇒B=A; transitive A=B,B=C⇒A=C.',31,'1–4'),('Variables on each side','متغيرات في طرفي المعادلة','Collect variable terms on one side and constants on the other.',97,'1–4'),('Distribute to evaluate','التوزيع للحساب الذهني','Rewrite a factor as a nearby convenient value plus or minus a small number.',37,'Example 2; Check'),('Rate of change','معدل التغير','A linear function has a constant Δy/Δx.',221,'Examples 3–4; Check'),('Solve proportions','حل التناسب','For b,d≠0, a/b=c/d implies ad=bc.',113,'13–16'),('Multi-step equations with parameters','معادلات متعددة الخطوات بمعاملات','Undo constants before dividing by a nonzero coefficient.',89,'18–21'),('Dilations of linear functions','التمدد لدوال خطية','Relative to y=x, kx stretches vertically if |k|>1 and compresses if 0<|k|<1.',248,'10–12,14'),('Slope-intercept form','صيغة الميل والمقطع','Isolate y to obtain y=mx+b.',235,'9–12'),('Read linear graphs','قراءة الرسوم الخطية','Slope is rise/run; b is where the line crosses the y-axis.',236,'37–39; p233 graph A'),('Graph step functions','رسم الدوال الدرجية','⌊x⌋ is the greatest integer ≤x; pay attention to open and closed endpoints.',263,'7–9; 7 domain/range'),('Slope from two points','الميل بين نقطتين','m=(y₂−y₁)/(x₂−x₁); vertical lines have undefined slope.',223,'Examples 6–8; Check a'),('Evaluate step functions','إيجاد قيم الدوال الدرجية','Evaluate the expression inside the floor brackets first.',265,'18a–18d'),('Arithmetic sequence arguments','تبرير المتتاليات الحسابية','Check that all consecutive differences are equal.',257,'28–31'),('Constant linear functions','الدوال الخطية الثابتة','y=b is horizontal, with slope 0 and y-intercept b.',233,'Graphs C,D; p236 25–26'),('Verbal expressions','التعابير اللفظية','Translate each operation and preserve subtraction/division order.',18,'1–4'),('Solve multi-step equations','حل المعادلات متعددة الخطوات','Distribute if needed, combine like terms, then use inverse operations.',89,'27,29,33,34'),('Evaluate algebraic expressions','إيجاد قيم التعابير الجبرية','Substitute first, then powers, multiplication/division, addition/subtraction.',19,'42–45'),('Use and rearrange formulas','تطبيق الصيغ وإعادة ترتيبها','Rearrange symbolically before substituting numerical values.',125,'19–22'),('Equations, identities and contradictions','المعادلات والمتطابقات والتناقض','A true constant statement is an identity; a false one means no solution.',97,'7,11; p99 37,39'),('Graph with a table','الرسم باستخدام جدول','Choose convenient x-values, calculate y, and plot collinear points.',215,'5–8'),('Piecewise functions','الدوال متعددة التعريف','Use each formula only on its stated interval; show endpoint inclusion.',263,'1–4'),('Arithmetic nth term','الحد النوني للمتتالية الحسابية','aₙ=a₁+(n−1)d; substitute the requested term number.',255,'19–22')]
outcomes=[]
for i,(title,ar,rule,page,ex) in enumerate(topics,1):
 group=[q for q in questions if q['learning_outcome_id']==f'LO{i:02}'];assert len(group)==4
 outcomes.append(dict(id=f'LO{i:02}',exam_slot=f'Q{i}',title=title,title_ar=ar,statement=title,question_type='mcq' if i<=20 else 'frq',rule_summary=rule,textbook_references=[dict(printed_page=page,exercises_or_section=ex)],question_count=4,question_ids=[q['id'] for q in group],booklet_question_ids=[q['id'] for q in group],download=f'LO{i:02}.json'))
assert len(questions)==104
provenance=dict(parts=parts,selection_policy='Book only: original numbers and original visual crops. MCQ options and worked keys are added. Repeated exercise references identify distinct original subparts or graph/domain questions. No final-exam prediction is claimed.',learning_outcomes=outcomes,questions=questions)
bank=dict(id='9g3-term1',classroom='9G3',title='Term 1 textbook question bank',title_ar='بنك الفصل الأول من الكتاب فقط',term=1,academic_year='2026–2027',content_version='textbook-v1',mock_storage_namespace='9g3-term1-textbook-v1',source_sha256=hashlib.sha256(json.dumps(parts,sort_keys=True).encode()).hexdigest(),source_parts=parts,source_file='provenance.json',question_count=104,mcq_count=80,frq_count=24,questions=questions,learning_outcomes=outcomes,assets=assets,authored_notice='Selected original exercises from the two uploaded Grade 9 books, aligned to the supplied 26 learning outcomes. MCQ choices and worked answers are added. Some cited exercises contribute distinct subparts. Practice only; the one-hour mock is not the official final exam.',authored_notice_ar='أسئلة أصلية من جزأي كتاب التاسع المرفقين، مرتبة حسب 26 مخرج تعلم، مع خيارات وحلول مضافة. بعض التمارين موزعة إلى أجزاء مستقلة. الاختبار التجريبي تدريب مدته ساعة وليس اختبارًا رسميًا.',study_booklet='worksheets/grade-9-general-term1-study-booklet.pdf',review_notes={})
for name,data in [('index.json',bank),('bank.json',bank),('provenance.json',provenance)]: (OUT/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
for o in outcomes:
 group=[q for q in questions if q['id'] in o['question_ids']];used={id for q in group for id in q['diagram_asset_ids']};(OUT/o['download']).write_text(json.dumps(dict(bank_metadata=dict(id='9g3-term1-'+o['id'],classroom='9G3',learning_outcome_id=o['id'],question_count=4),learning_outcomes=[o],questions=group,assets={id:assets[id] for id in used}),ensure_ascii=False,indent=2)+'\n')
(ROOT/'content-imports/grade9-general-textbook-selection.json').write_text(json.dumps(provenance,ensure_ascii=False,indent=2)+'\n')
print('9G3 textbook bank:',len(questions),'questions,',len(assets),'original visual crops.')
